  "headline": "Pegfilgrastim is not on FDA's shortage list as of 2026-10-21; Corvale East has 14.6 days on hand and Corvale General has 27.4 days on hand",
  "headline_cites": ["D3", "D1", "D2"],
  "sentences": [
    {
      "text": "FDA's records show pegfilgrastim is not on the drug shortage list as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 41 syringes at 2.8 per day, giving 14.6 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 157 syringes at 5.7 per day, giving 27.4 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "A label for pegfilgrastim names Kashiv BioSciences, LLC as the plant (FEI 3011289655) with operations including manufacture.",
      "cites": ["E7"]
    },
    {
      "text": "FDA inspected that plant on 2024-06-14 and classified it VAI, with the classification known on 2024-08-16.",
      "cites": ["E6"]
    },
    {
      "text": "The same plant received an OAI classification after an inspection ending 2018-01-26, known on 2018-02-16.",
      "cites": ["E5"]
    },
    {
      "text": "The rule-based best option is to buy from Accord BioPharma, Inc., which is not on FDA's shortage list today and whose label names no plant we could place.",
      "cites": ["D4"]
    }
  ]
}
